CREATE DATABASE IF NOT EXISTS sticky_order_dashboard CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE sticky_order_dashboard;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('super_admin','admin','user') NOT NULL DEFAULT 'user',is_active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL) ENGINE=InnoDB;
CREATE TABLE brands (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,campaign_ids VARCHAR(2000) NOT NULL DEFAULT '',logo VARCHAR(255) NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL,INDEX(is_active)) ENGINE=InnoDB;
CREATE TABLE user_brands (user_id BIGINT UNSIGNED NOT NULL,brand_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(user_id,brand_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(brand_id) REFERENCES brands(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE settings (setting_key VARCHAR(100) PRIMARY KEY,setting_value MEDIUMTEXT NOT NULL,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE permissions (role ENUM('admin','user') NOT NULL,permission_key VARCHAR(100) NOT NULL,allowed TINYINT(1) NOT NULL DEFAULT 0,PRIMARY KEY(role,permission_key)) ENGINE=InnoDB;
CREATE TABLE password_resets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(expires_at)) ENGINE=InnoDB;
CREATE TABLE audit_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,detail VARCHAR(250) NULL,ip_address VARCHAR(45) NULL,created_at DATETIME NOT NULL,INDEX(created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
INSERT INTO permissions(role,permission_key,allowed) VALUES
('admin','brands.manage',1),('admin','users.manage',0),('admin','settings.manage',0),
('user','brands.manage',0),('user','users.manage',0),('user','settings.manage',0);
